"""CITATION.cff is generated by scripts/showcase.py, a must-pass pipeline stage.

The abstract once said "No model is trained", although this repository trained
the v0.3.0 distill and the five-seed study LoRA adapters. Correcting only the
committed CITATION.cff did not last, because the next pipeline run regenerated
the old sentence. These tests run the generator in a scratch directory, so
nothing in the checkout is rewritten.
"""
import json
import re
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SCRIPT = ROOT / "scripts" / "showcase.py"


def run_showcase(workdir, edit=None):
    # Copy every receipt the generator reads, found from its own rd("...") calls.
    for rel in sorted(set(re.findall(r'rd\("([^"]+)"\)', SCRIPT.read_text(encoding="utf-8")))):
        if (ROOT / rel).exists():
            (workdir / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(ROOT / rel, workdir / rel)
    for rel in ("docs/showcase", "docs/announce"):
        (workdir / rel).mkdir(parents=True, exist_ok=True)
    if edit:
        edit(workdir)
    return subprocess.run([sys.executable, str(SCRIPT)], cwd=workdir, capture_output=True,
                          text=True, timeout=120)


def test_showcase_regenerates_the_committed_citation(tmp_path):
    result = run_showcase(tmp_path)
    assert result.returncode == 0, result.stderr
    assert (tmp_path / "CITATION.cff").read_bytes() == (ROOT / "CITATION.cff").read_bytes()


def test_citation_does_not_say_that_no_model_is_trained():
    text = (ROOT / "CITATION.cff").read_text(encoding="utf-8")
    assert "No model is trained" not in text
    assert "NOT_PROMOTABLE" in text


def test_showcase_refuses_before_writing_when_a_release_receipt_changes(tmp_path):
    def promote(workdir):
        path = workdir / "out" / "release_gate.json"
        receipt = json.loads(path.read_text(encoding="utf-8-sig"))
        receipt["release_verdict"] = "PROMOTABLE"
        path.write_text(json.dumps(receipt), encoding="utf-8")

    result = run_showcase(tmp_path, promote)
    assert result.returncode != 0
    assert "rewrite the CITATION.cff abstract" in result.stderr
    assert not (tmp_path / "CITATION.cff").exists()
    assert not any((tmp_path / "docs" / "showcase").iterdir())
